import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

const val MaxN = 2023
const val MOD = 998244353L

var pless = 0L
var pgreater = 0L
val CP = Array(MaxN) { LongArray(MaxN) }
val STRONG = LongArray(MaxN)
val ans = LongArray(MaxN)

fun bpow(a: Long, b: Long): Long {
    if (b == 0L) return 1L
    var res = bpow(a, b shr 1)
    res = (res * res) % MOD
    if (b and 1L == 1L) res = (res * a) % MOD
    return res
}

fun calcCP(n: Int, s: Int) {
    if (s == 0) {
        CP[n][s] = 1L
    } else {
        CP[n][s] = (CP[n - 1][s - 1] * bpow(pgreater, (n - s).toLong())) % MOD +
                (CP[n - 1][s] * bpow(pless, s.toLong())) % MOD
        if (CP[n][s] >= MOD) CP[n][s] -= MOD
    }
}

fun calcStrong(n: Int) {
    STRONG[n] = 1L
    if (n > 1) {
        for (i in 1 until n) {
            STRONG[n] -= (STRONG[i] * CP[n][i]) % MOD
            if (STRONG[n] < 0) STRONG[n] += MOD
        }
    }
}

fun calcAns(n: Int) {
    if (n < 2) {
        ans[n] = 0L
    } else {
        for (i in 1..n) {
            val innerTerm = (i.toLong() * (n - i) + (i.toLong() * (i - 1)) / 2 +
                    (if (i < n) ans[i] else 0L) + ans[n - i]) % MOD
            val term = STRONG[i] * CP[n][i] % MOD * innerTerm % MOD
            ans[n] += term
            if (ans[n] >= MOD) ans[n] -= MOD
        }
        var coef = 1L - (STRONG[n] * CP[n][n]) % MOD
        if (coef < 0) coef += MOD
        ans[n] = (ans[n] * bpow(coef, MOD - 2)) % MOD
    }
}

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(br.readLine())
    val n = st.nextToken().toInt()
    val a = st.nextToken().toInt()
    val b = st.nextToken().toInt()

    pless = (a.toLong() * bpow(b.toLong(), MOD - 2)) % MOD
    pgreater = ((b - a).toLong() * bpow(b.toLong(), MOD - 2)) % MOD

    for (i in 0..n)
        for (j in 0..i)
            calcCP(i, j)

    for (i in 0..n)
        calcStrong(i)

    for (i in 0..n)
        calcAns(i)

    println(ans[n])
}
